### 4. BASE CLIENT & ARCHITECTURE

#### BaseEsiClient
**File**: `/d/code/ESI.ts/src/clients/BaseEsiClient.ts`

```typescript
import { ApiClient } from '../core/ApiClient';
import {
  createClient,
  CreateClientOptions,
  WithMetadata,
} from '../core/endpoints/createClient';
import { EndpointMap } from '../core/endpoints/EndpointDefinition';

type ClientMethods<T extends EndpointMap> = ReturnType<typeof createClient<T>>;

export abstract class BaseEsiClient<T extends EndpointMap> {
  protected api: ClientMethods<T>;
  protected _client: ApiClient;
  private _endpoints: T;
  private _metaApi?: ClientMethods<T>;

  constructor(client: ApiClient, endpoints: T) {
    this._client = client;
    this._endpoints = endpoints;
    this.api = createClient(client, endpoints);
  }

  withMetadata(): WithMetadata<Omit<this, 'withMetadata'>> {
    if (!this._metaApi) {
      this._metaApi = createClient(this._client, this._endpoints, {
        returnMetadata: true,
      } as CreateClientOptions);
    }
    return this._metaApi as unknown as WithMetadata<Omit<this, 'withMetadata'>>;
  }
}
```

**Pattern**: Generic base class parameterized by EndpointMap. All clients inherit from this. The `withMetadata()` method provides optional response metadata.

#### SovereigntyClient Implementation
**File**: `/d/code/ESI.ts/src/clients/SovereigntyClient.ts`

```typescript
import { ApiClient } from '../core/ApiClient';
import { BaseEsiClient } from './BaseEsiClient';
import { sovereigntyEndpoints } from '../core/endpoints/sovereigntyEndpoints';
import {
  SovereigntyCampaign,
  SovereigntyMap,
  SovereigntyStructure,
} from '../types/api-responses';

export class SovereigntyClient extends BaseEsiClient<
  typeof sovereigntyEndpoints
> {
  constructor(client: ApiClient) {
    super(client, sovereigntyEndpoints);
  }

  /**
   * Retrieves all active sovereignty campaigns, including command node contests and station freeports.
   *
   * @returns A list of active sovereignty campaigns
   */
  getSovereigntyCampaigns(): Promise<SovereigntyCampaign[]> {
    return this.api.getSovereigntyCampaigns() as Promise<SovereigntyCampaign[]>;
  }

  /**
   * Retrieves the sovereignty ownership map showing which alliance holds each solar system.
   *
   * @returns A list of solar systems and their sovereignty holders
   */
  getSovereigntyMap(): Promise<SovereigntyMap[]> {
    return this.api.getSovereigntyMap() as Promise<SovereigntyMap[]>;
  }

  /**
   * Retrieves all sovereignty structures (TCUs, IHubs) and their vulnerability windows.
   *
   * @returns A list of sovereignty structures with their reinforcement and vulnerability details
   */
  getSovereigntyStructures(): Promise<SovereigntyStructure[]> {
    return this.api.getSovereigntyStructures() as Promise<
      SovereigntyStructure[]
    >;
  }
}
```

